const selectExpiredLeases = `-- name: SelectExpiredLeases :many
SELECT id, queue, type, attempts, max_attempts, backoff, cancel_requested
  FROM jobs
 WHERE status = 'leased' AND lease_until < $1::timestamptz
 ORDER BY lease_until
 LIMIT $2
   FOR UPDATE SKIP LOCKED
`

type SelectExpiredLeasesParams struct {
	Now        time.Time
	BatchLimit int32
}

type SelectExpiredLeasesRow struct {
	ID              uuid.UUID
	Queue           string
	Type            string
	Attempts        int32
	MaxAttempts     int32
	Backoff         []byte
	CancelRequested bool
}

// Reaper step 1 (inside the reaper transaction). Step 2 is RequeueExpired with the
// per-id verdict computed in Go so the backoff policy has exactly one implementation.
func (q *Queries) SelectExpiredLeases(ctx context.Context, arg SelectExpiredLeasesParams) ([]SelectExpiredLeasesRow, error) {
	rows, err := q.db.Query(ctx, selectExpiredLeases, arg.Now, arg.BatchLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SelectExpiredLeasesRow{}
	for rows.Next() {
		var i SelectExpiredLeasesRow
		if err := rows.Scan(
			&i.ID,
			&i.Queue,
			&i.Type,
			&i.Attempts,
			&i.MaxAttempts,
			&i.Backoff,
			&i.CancelRequested,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
